if not fn then return end
F=fn()
end
local function DECSTR(F,sk)
for _,p in pairs(F) do
local k=p.k
for i=1,#k do
local v=k[i]
if type(v)=='string' then
local o={}
for j=1,#v do
local b=sb(v,j)
local kk=sk[(j-1)%#sk+1]
local r,q=0,1
local x,y=b,kk
while x>0 or y>0 do
local xa,ya=x%2,y%2
if xa~=ya then r=r+q end
x=(x-xa)/2 y=(y-ya)/2 q=q*2
end
o[#o+1]=sc(r)
end
k[i]=table.concat(o)
end
end
end
end
