local ENV = getfenv and getfenv(0) or _G
local tunpack, tpack = table.unpack, table.pack
local mfloor, bnot = math.floor, ((bit32 and bit32.bnot) or function(x) return x end)
local VM
local function GUARD()
local need = { 'table', 'string', 'math', 'type', 'pcall', 'select' }
for i = 1, #need do
if _G[need[i]] == nil then return false end
end
