R[a] = r1
if r2 ~= nil then R[a + 1] = r2 end
if r3 ~= nil then R[a + 2] = r3 end
else R[a] = fn() end
elseif n == 1 then
if op == 67 then
local r1, r2, r3 = fn(R[b + 1])
R[a] = r1
if r2 ~= nil then R[a + 1] = r2 end
if r3 ~= nil then R[a + 2] = r3 end
else R[a] = fn(R[b + 1]) end
elseif n == 2 then
